{
  "name": "Q-Crop",
  "description": "An AI-powered tool to automatically detect, crop, and export individual questions from scanned exam pages or test papers."
}

import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';

const rootElement = document.getElementById('root');
if (!rootElement) {
  throw new Error("Could not find root element to mount to");
}

const root = ReactDOM.createRoot(rootElement);
root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

export interface BoundingBox {
  ymin: number;
  xmin: number;
  ymax: number;
  xmax: number;
}

export interface QuestionRegion {
  id: string;
  questionNumber: string;
  box: BoundingBox;
  croppedDataUrl?: string;
  isSelected?: boolean;
}

export type AppStatus = 'IDLE' | 'ANALYZING' | 'READY' | 'ERROR';

import { GoogleGenAI, Type } from "@google/genai";
import { QuestionRegion } from "../types";

// Initialize AI inside functions to ensure latest API key if applicable
const getAI = () => new GoogleGenAI({ apiKey: process.env.API_KEY });

export const analyzeTestPage = async (base64Image: string, mimeType: string): Promise<Omit<QuestionRegion, 'id' | 'croppedDataUrl'>[]> => {
  const ai = getAI();

  const prompt = `
    Analyze this image of a test paper or worksheet. 
    Identify every distinct question block. A question block typically starts with a number (e.g., "1.", "13.", "Q1") and includes its associated text, options (A, B, C, D, E), and any associated images or graphs directly relevant to that specific question.

    For each identified question, provide:
    1. The question number as a string.
    2. A precise bounding box encompassing the ENTIRE question (text, options, internal images). 

    IMPORTANT BOUNDING BOX RULES:
    - Coordinates MUST be integers between 0 and 1000.
    - They represent relative positions where [0,0] is the top-left corner of the image and [1000, 1000] is the bottom-right corner.
    - ymin: Top edge of the box
    - xmin: Left edge of the box
    - ymax: Bottom edge of the box
    - xmax: Right edge of the box
    - Ensure ymax is strictly greater than ymin, and xmax is strictly greater than xmin.
    - Make sure to leave a small margin around the text so nothing is cut off.
  `;

  try {
    const response = await ai.models.generateContent({
      model: "gemini-3-flash-preview", // Good balance of speed and vision capability
      contents: [
        {
          inlineData: {
            data: base64Image,
            mimeType: mimeType,
          },
        },
        { text: prompt }
      ],
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.ARRAY,
          description: "List of detected questions.",
          items: {
            type: Type.OBJECT,
            properties: {
              questionNumber: {
                type: Type.STRING,
                description: "The number or label of the question (e.g., '1', '13', '14a')."
              },
              ymin: { type: Type.INTEGER, description: "Top Y coordinate (0-1000)" },
              xmin: { type: Type.INTEGER, description: "Left X coordinate (0-1000)" },
              ymax: { type: Type.INTEGER, description: "Bottom Y coordinate (0-1000)" },
              xmax: { type: Type.INTEGER, description: "Right X coordinate (0-1000)" }
            },
            required: ["questionNumber", "ymin", "xmin", "ymax", "xmax"]
          }
        }
      }
    });

    if (!response.text) {
      throw new Error("Empty response from AI");
    }

    const parsedData = JSON.parse(response.text);

    // Map the raw JSON response to our expected interface format
    return parsedData.map((item: any) => ({
      questionNumber: item.questionNumber,
      box: {
        ymin: item.ymin,
        xmin: item.xmin,
        ymax: item.ymax,
        xmax: item.xmax
      }
    }));

  } catch (error) {
    console.error("Error analyzing test page:", error);
    throw new Error("Failed to analyze the image. Please try again.");
  }
};

