import React, { useCallback, useRef } from 'react';
import { UploadIcon } from './Icons';

interface UploaderProps {
  onImageSelected: (dataUrl: string, file: File) => void;
  isLoading: boolean;
}

const Uploader: React.FC<UploaderProps> = ({ onImageSelected, isLoading }) => {
  const fileInputRef = useRef<HTMLInputElement>(null);

  const handleFileChange = useCallback((event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (file && file.type.startsWith('image/')) {
      const reader = new FileReader();
      reader.onload = (e) => {
        if (e.target?.result && typeof e.target.result === 'string') {
          onImageSelected(e.target.result, file);
        }
      };
      reader.readAsDataURL(file);
    } else if (file && file.type === 'application/pdf') {
      alert("PDF support is coming soon! For now, please upload image formats (JPG, PNG). You can easily convert a PDF to images first.");
    }
    // Reset input so the same file can be selected again if needed
    if (fileInputRef.current) {
        fileInputRef.current.value = '';
    }
  }, [onImageSelected]);

  return (
    <div className="flex flex-col items-center justify-center w-full h-full p-8">
      <div 
        className={`w-full max-w-2xl p-12 border-2 border-dashed rounded-xl text-center transition-colors
          ${isLoading ? 'border-gray-300 bg-gray-50 opacity-70 pointer-events-none' : 'border-brand-500 bg-brand-50 hover:bg-brand-100 cursor-pointer'}
        `}
        onClick={() => !isLoading && fileInputRef.current?.click()}
      >
        <UploadIcon className={`mx-auto w-16 h-16 mb-4 ${isLoading ? 'text-gray-400' : 'text-brand-500'}`} />
        <h3 className="text-xl font-semibold mb-2 text-gray-800">Upload Exam Page</h3>
        <p className="text-gray-500 mb-6">Drag and drop an image, or click to browse.</p>
        <p className="text-sm text-gray-400">Supports JPG, PNG (Max 10MB)</p>

        <input 
          type="file" 
          ref={fileInputRef}
          onChange={handleFileChange}
          accept="image/jpeg, image/png, image/webp" 
          className="hidden" 
        />
      </div>
    </div>
  );
};

export default Uploader;

import React, { useState, useEffect, useRef, useCallback } from 'react';
import Uploader from './components/Uploader';
import { analyzeTestPage } from './services/geminiService';
import { QuestionRegion, AppStatus } from './types';
import { LoaderIcon, CheckIcon, DownloadIcon, ScissorsIcon } from './components/Icons';

export default function App() {
  const [status, setStatus] = useState<AppStatus>('IDLE');
  const [errorMsg, setErrorMsg] = useState<string>('');

  // Image data
  const [imageFile, setImageFile] = useState<File | null>(null);
  const [imageDataUrl, setImageDataUrl] = useState<string | null>(null);
  const [imageObj, setImageObj] = useState<HTMLImageElement | null>(null);

  // App Data
  const [regions, setRegions] = useState<QuestionRegion[]>([]);

  // Canvas Refs
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const containerRef = useRef<HTMLDivElement>(null);

  // Helper to generate a unique ID
  const generateId = () => Math.random().toString(36).substr(2, 9);

  // Handle new image upload
  const handleImageSelected = useCallback(async (dataUrl: string, file: File) => {
    setImageDataUrl(dataUrl);
    setImageFile(file);
    setStatus('ANALYZING');
    setErrorMsg('');
    setRegions([]);

    // Load image object for cropping later
    const img = new Image();
    img.onload = async () => {
      setImageObj(img);

      try {
        // Prepare base64 for API (remove data URI prefix)
        const base64String = dataUrl.split(',')[1];

        // Call Gemini API
        const detectedRegions = await analyzeTestPage(base64String, file.type);

        // Add IDs to regions
        const regionsWithIds: QuestionRegion[] = detectedRegions.map(r => ({
          ...r,
          id: generateId()
        }));

        setRegions(regionsWithIds);
        setStatus('READY');
      } catch (err: any) {
        setStatus('ERROR');
        setErrorMsg(err.message || "An error occurred during analysis.");
      }
    };
    img.onerror = () => {
      setStatus('ERROR');
      setErrorMsg("Failed to load the image locally.");
    };
    img.src = dataUrl;
  }, []);

  // Process crops when regions or imageObj changes
  useEffect(() => {
    if (status === 'READY' && imageObj && regions.length > 0 && !regions[0].croppedDataUrl) {
      const generateCrops = async () => {
        const updatedRegions = [...regions];
        for (let i = 0; i < updatedRegions.length; i++) {
          const region = updatedRegions[i];
          if (!region.croppedDataUrl) {
             updatedRegions[i] = {
                 ...region,
                 croppedDataUrl: cropImage(imageObj, region.box)
             };
          }
        }
        setRegions(updatedRegions);
      };
      generateCrops();
    }
  // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [status, imageObj, regions]);


  // Draw main canvas
  useEffect(() => {
    if (status !== 'READY' && status !== 'ANALYZING') return;
    if (!imageObj || !canvasRef.current || !containerRef.current) return;

    const canvas = canvasRef.current;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    const container = containerRef.current;

    // Fit canvas to container while maintaining aspect ratio
    const containerRatio = container.clientWidth / container.clientHeight;
    const imageRatio = imageObj.width / imageObj.height;

    let drawWidth = container.clientWidth;
    let drawHeight = container.clientHeight;

    if (containerRatio > imageRatio) {
      drawWidth = drawHeight * imageRatio;
    } else {
      drawHeight = drawWidth / imageRatio;
    }

    canvas.width = drawWidth;
    canvas.height = drawHeight;

    // Draw image
    ctx.drawImage(imageObj, 0, 0, drawWidth, drawHeight);

    // Draw overlays if READY
    if (status === 'READY') {
      regions.forEach(region => {
        const { ymin, xmin, ymax, xmax } = region.box;

        // Convert 0-1000 scale to actual canvas pixels
        const startX = (xmin / 1000) * drawWidth;
        const startY = (ymin / 1000) * drawHeight;
        const width = ((xmax - xmin) / 1000) * drawWidth;
        const height = ((ymax - ymin) / 1000) * drawHeight;

        // Draw rectangle
        ctx.beginPath();
        ctx.rect(startX, startY, width, height);

        if (region.isSelected) {
          ctx.fillStyle = 'rgba(34, 197, 94, 0.2)'; // Brand color with opacity
          ctx.fill();
          ctx.lineWidth = 3;
          ctx.strokeStyle = '#16a34a';
        } else {
           ctx.fillStyle = 'rgba(59, 130, 246, 0.1)'; // Blue with opacity
           ctx.fill();
           ctx.lineWidth = 2;
           ctx.strokeStyle = 'rgba(59, 130, 246, 0.8)';
        }
        ctx.stroke();

        // Draw Badge
        ctx.fillStyle = region.isSelected ? '#16a34a' : 'rgba(59, 130, 246, 0.9)';
        ctx.font = 'bold 14px sans-serif';
        const text = `Q${region.questionNumber}`;
        const textMetrics = ctx.measureText(text);
        const textWidth = textMetrics.width;

        // Badge background
        ctx.fillRect(startX, startY - 24 > 0 ? startY - 24 : startY, textWidth + 16, 24);

        // Badge text
        ctx.fillStyle = 'white';
        ctx.fillText(text, startX + 8, (startY - 24 > 0 ? startY - 8 : startY + 16));
      });
    }

  }, [imageObj, regions, status, containerRef.current?.clientWidth, containerRef.current?.clientHeight]); // re-render on resize if possible, though exact resize listener needs more work

  // Handle Resize to re-draw canvas
  useEffect(() => {
    const handleResize = () => {
        // Trigger a fake state update to force re-evaluation of canvas draw
        setRegions(prev => [...prev]);
    };
    window.addEventListener('resize', handleResize);
    return () => window.removeEventListener('resize', handleResize);
  }, []);


  // Helper function to crop the actual high-res image
  const cropImage = (img: HTMLImageElement, box: typeof regions[0]['box']): string => {
    const offscreenCanvas = document.createElement('canvas');
    const ctx = offscreenCanvas.getContext('2d');
    if (!ctx) return '';

    const { ymin, xmin, ymax, xmax } = box;

    const sourceX = (xmin / 1000) * img.width;
    const sourceY = (ymin / 1000) * img.width; // Bug fix: usually it's img.height for Y, but let's check standard practice. Wait, 0-1000 is relative.
    const actualSourceY = (ymin / 1000) * img.height;
    const sourceWidth = ((xmax - xmin) / 1000) * img.width;
    const sourceHeight = ((ymax - ymin) / 1000) * img.height;

    // Optional padding (e.g., 2% of width)
    const paddingX = img.width * 0.01;
    const paddingY = img.height * 0.01;

    // Apply padding with bounds checking
    const finalSX = Math.max(0, sourceX - paddingX);
    const finalSY = Math.max(0, actualSourceY - paddingY);
    const finalSW = Math.min(img.width - finalSX, sourceWidth + (paddingX * 2));
    const finalSH = Math.min(img.height - finalSY, sourceHeight + (paddingY * 2));

    offscreenCanvas.width = finalSW;
    offscreenCanvas.height = finalSH;

    // Optional: Fill with white background in case of transparent PNGs
    ctx.fillStyle = '#ffffff';
    ctx.fillRect(0, 0, finalSW, finalSH);

    ctx.drawImage(
      img,
      finalSX, finalSY, finalSW, finalSH,
      0, 0, finalSW, finalSH
    );

    return offscreenCanvas.toDataURL('image/jpeg', 0.9); // Quality 0.9
  };

  const handleDownloadCrop = (region: QuestionRegion) => {
    if (!region.croppedDataUrl) return;
    const link = document.createElement('a');
    link.href = region.croppedDataUrl;
    link.download = `Question_${region.questionNumber}.jpg`;
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  };

  const handleDownloadAll = () => {
    regions.forEach(region => {
      if (region.croppedDataUrl) {
         // Slight delay to prevent browser blocking multiple rapid downloads
         setTimeout(() => handleDownloadCrop(region), 100);
      }
    });
  };

  const handleSelectRegion = (id: string) => {
    setRegions(prev => prev.map(r => ({
      ...r,
      isSelected: r.id === id
    })));
  };

  const handleReset = () => {
    setStatus('IDLE');
    setImageFile(null);
    setImageDataUrl(null);
    setImageObj(null);
    setRegions([]);
  };

  return (
    <>
      <header className="bg-white border-b border-gray-200 px-6 py-4 flex items-center justify-between shrink-0 sticky top-0 z-10">
        <div className="flex items-center gap-3">
          <div className="bg-brand-500 text-white p-2 rounded-lg">
            <ScissorsIcon className="w-5 h-5" />
          </div>
          <h1 className="text-xl font-bold text-gray-800 tracking-tight">Q-Crop</h1>
        </div>

        {status !== 'IDLE' && (
          <button 
            onClick={handleReset}
            className="text-sm font-medium text-gray-500 hover:text-gray-800 transition-colors"
          >
            Start Over
          </button>
        )}
      </header>

      <main className="flex-1 flex overflow-hidden">
        {status === 'IDLE' && (
           <Uploader onImageSelected={handleImageSelected} isLoading={false} />
        )}

        {(status === 'ANALYZING' || status === 'ERROR') && !regions.length && (
           <div className="flex-1 flex flex-col items-center justify-center p-8 text-center bg-gray-50">
              {status === 'ANALYZING' && (
                 <>
                   <LoaderIcon className="w-12 h-12 text-brand-500 mb-6" />
                   <h2 className="text-2xl font-semibold text-gray-800 mb-2">Analyzing Document...</h2>
                   <p className="text-gray-500 max-w-md">Our AI is scanning the image to identify and map out individual questions. This usually takes a few seconds.</p>
                 </>
              )}
              {status === 'ERROR' && (
                 <>
                   <div className="w-16 h-16 bg-red-100 text-red-600 rounded-full flex items-center justify-center mb-6">
                      <svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" strokeWidth={1.5} stroke="currentColor" className="w-8 h-8">
                        <path strokeLinecap="round" strokeLinejoin="round" d="M12 9v2m0 4h.01m-6.938 4h13.856c1.54 0 2.502-1.667 1.732-3L13.732 4c-.77-1.333-2.694-1.333-3.464 0L3.34 16c-.77 1.333.192 3 1.732 3z" />
                      </svg>
                   </div>
                   <h2 className="text-2xl font-semibold text-gray-800 mb-2">Analysis Failed</h2>
                   <p className="text-red-500 mb-6 max-w-md">{errorMsg}</p>
                   <button 
                     onClick={handleReset}
                     className="px-6 py-2 bg-gray-800 text-white rounded-lg hover:bg-gray-700 font-medium transition-colors"
                   >
                     Try Another Image
                   </button>
                 </>
              )}
           </div>
        )}

        {/* Main Workspace Workspace */}
        {(status === 'READY' || (status === 'ANALYZING' && imageDataUrl)) && (
          <div className="flex-1 flex w-full h-full">

            {/* Canvas Area */}
            <div className="flex-1 bg-gray-200 p-4 overflow-hidden relative" ref={containerRef}>
                <div className="w-full h-full flex items-center justify-center relative shadow-inner bg-gray-300 rounded-lg overflow-hidden border border-gray-300">
                    <canvas 
                      ref={canvasRef} 
                      className="block max-w-full max-h-full shadow-lg bg-white"
                      style={{ objectFit: 'contain' }}
                    />

                    {/* Overlay Loader if re-analyzing */}
                    {status === 'ANALYZING' && (
                      <div className="absolute inset-0 bg-white/50 backdrop-blur-sm flex items-center justify-center z-10">
                         <LoaderIcon className="w-10 h-10 text-brand-600" />
                      </div>
                    )}
                </div>
            </div>

            {/* Sidebar */}
            <div className="w-96 bg-white border-l border-gray-200 flex flex-col shrink-0 shadow-[-4px_0_15px_-3px_rgba(0,0,0,0.05)] z-20">

              <div className="p-5 border-b border-gray-100 bg-gray-50/50 shrink-0">
                <div className="flex justify-between items-center mb-1">
                  <h2 className="text-lg font-bold text-gray-800">Detected Questions</h2>
                  <span className="bg-brand-100 text-brand-700 text-xs font-bold px-2 py-1 rounded-full">
                    {regions.length} Found
                  </span>
                </div>
                <p className="text-sm text-gray-500 mb-4">Review crops and export individually or all at once.</p>

                <button
                  onClick={handleDownloadAll}
                  disabled={regions.length === 0 || !regions.every(r => r.croppedDataUrl)}
                  className="w-full bg-brand-600 hover:bg-brand-700 text-white font-medium py-2.5 px-4 rounded-lg flex items-center justify-center gap-2 transition-colors disabled:opacity-50 disabled:cursor-not-allowed shadow-sm"
                >
                  <DownloadIcon className="w-5 h-5" />
                  Export All as JPG ZIP
                </button>
              </div>

              <div className="flex-1 overflow-y-auto p-4 space-y-4">
                {regions.map((region) => (
                  <div 
                    key={region.id} 
                    className={`border rounded-xl overflow-hidden transition-all duration-200 shadow-sm
                      ${region.isSelected ? 'border-brand-500 ring-2 ring-brand-100' : 'border-gray-200 hover:border-gray-300'}
                    `}
                    onClick={() => handleSelectRegion(region.id)}
                  >
                    <div className="bg-gray-50 px-3 py-2 border-b border-gray-100 flex justify-between items-center cursor-pointer">
                      <span className="font-semibold text-gray-700 flex items-center gap-2">
                         <div className={`w-2 h-2 rounded-full ${region.isSelected ? 'bg-brand-500' : 'bg-gray-300'}`}></div>
                         Question {region.questionNumber}
                      </span>
                      <button
                        onClick={(e) => { e.stopPropagation(); handleDownloadCrop(region); }}
                        disabled={!region.croppedDataUrl}
                        className="text-gray-400 hover:text-brand-600 p-1 rounded transition-colors disabled:opacity-50"
                        title="Download this crop"
                      >
                         <DownloadIcon className="w-5 h-5" />
                      </button>
                    </div>

                    <div className="bg-white p-3 cursor-pointer relative group">
                      {region.croppedDataUrl ? (
                         <>
                           <img 
                              src={region.croppedDataUrl} 
                              alt={`Crop for question ${region.questionNumber}`}
                              className="w-full h-auto max-h-48 object-contain rounded border border-gray-100 bg-gray-50"
                           />
                           <div className="absolute inset-0 bg-black/5 opacity-0 group-hover:opacity-100 transition-opacity flex items-center justify-center pointer-events-none">
                              <span className="bg-white/90 text-gray-800 text-xs font-semibold px-2 py-1 rounded shadow-sm">View</span>
                           </div>
                         </>
                      ) : (
                         <div className="w-full h-24 flex items-center justify-center bg-gray-50 text-gray-400 text-sm">
                           Processing...
                         </div>
                      )}
                    </div>
                  </div>
                ))}

                {regions.length === 0 && status === 'READY' && (
                   <div className="text-center py-10 text-gray-500">
                     <p>No questions detected.</p>
                     <p className="text-sm mt-2">Try a clearer image or a different page.</p>
                   </div>
                )}
              </div>

            </div>
          </div>
        )}
      </main>
    </>
  );
}

export interface BoundingBox {
  ymin: number;
  xmin: number;
  ymax: number;
  xmax: number;
}

export interface QuestionRegion {
  id: string;
  questionNumber: string;
  box: BoundingBox;
  contextBox?: BoundingBox; // Stores the bounding box of a shared paragraph/image if applicable
  croppedDataUrl?: string;
  isSelected?: boolean;
}

export type AppStatus = 'IDLE' | 'ANALYZING' | 'READY' | 'ERROR';

import { GoogleGenAI, Type } from "@google/genai";
import { QuestionRegion } from "../types";

// Initialize AI inside functions to ensure latest API key if applicable
const getAI = () => new GoogleGenAI({ apiKey: process.env.API_KEY });

export const analyzeTestPage = async (base64Image: string, mimeType: string): Promise<Omit<QuestionRegion, 'id' | 'croppedDataUrl'>[]> => {
  const ai = getAI();

  const prompt = `
    Analyze this image of a test paper or worksheet. 

    Sometimes, multiple questions refer to a shared block of text, a passage, an image, or a graph (e.g., "37 ve 38. soruları aşağıdaki parçaya göre cevaplayınız." or "Answer questions 37 and 38 based on the passage").

    Task 1: Identify "Shared Contexts". Draw bounding boxes around these shared passages/images along with their instructional text. Give each an ID (e.g., "c1", "c2").
    Task 2: Identify "Questions". A question block typically starts with a number (e.g., "37.", "Q1") and includes its text and options (A, B, C, D, E). 
    - DO NOT include the shared context in the question's bounding box. The question box should strictly contain just that specific question.
    - If a question relies on a shared context, include that context's ID in the 'contextId' field. If it does not, leave 'contextId' empty or omit it.

    IMPORTANT BOUNDING BOX RULES:
    - Coordinates MUST be integers between 0 and 1000.
    - They represent relative positions where [0,0] is the top-left corner of the image and [1000, 1000] is the bottom-right corner.
    - ymin: Top edge of the box
    - xmin: Left edge of the box
    - ymax: Bottom edge of the box
    - xmax: Right edge of the box
    - Ensure ymax is strictly greater than ymin, and xmax is strictly greater than xmin.
    - Make sure to leave a small margin around the text so nothing is cut off.
  `;

  try {
    const response = await ai.models.generateContent({
      model: "gemini-3-flash-preview", // Good balance of speed and vision capability
      contents: [
        {
          inlineData: {
            data: base64Image,
            mimeType: mimeType,
          },
        },
        { text: prompt }
      ],
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          description: "Structured test page data with shared contexts and questions.",
          properties: {
            sharedContexts: {
              type: Type.ARRAY,
              items: {
                type: Type.OBJECT,
                properties: {
                  id: { type: Type.STRING },
                  ymin: { type: Type.INTEGER },
                  xmin: { type: Type.INTEGER },
                  ymax: { type: Type.INTEGER },
                  xmax: { type: Type.INTEGER }
                },
                required: ["id", "ymin", "xmin", "ymax", "xmax"]
              }
            },
            questions: {
              type: Type.ARRAY,
              items: {
                type: Type.OBJECT,
                properties: {
                  questionNumber: { type: Type.STRING },
                  ymin: { type: Type.INTEGER },
                  xmin: { type: Type.INTEGER },
                  ymax: { type: Type.INTEGER },
                  xmax: { type: Type.INTEGER },
                  contextId: { type: Type.STRING, description: "ID of the shared context block this question relies on. Leave empty if none." }
                },
                required: ["questionNumber", "ymin", "xmin", "ymax", "xmax"]
              }
            }
          },
          required: ["sharedContexts", "questions"]
        }
      }
    });

    if (!response.text) {
      throw new Error("Empty response from AI");
    }

    const parsedData = JSON.parse(response.text);
    const contexts = parsedData.sharedContexts || [];
    const questions = parsedData.questions || [];

    // Create a lookup map for context bounding boxes
    const contextMap = new Map();
    contexts.forEach((c: any) => {
      if (c.id) {
        contextMap.set(c.id, {
          ymin: c.ymin, xmin: c.xmin, ymax: c.ymax, xmax: c.xmax
        });
      }
    });

    // Map the raw JSON response to our expected interface format
    return questions.map((q: any) => {
      const result: Omit<QuestionRegion, 'id' | 'croppedDataUrl'> = {
        questionNumber: q.questionNumber,
        box: { ymin: q.ymin, xmin: q.xmin, ymax: q.ymax, xmax: q.xmax }
      };

      // If this question maps to a shared context, attach that bounding box
      if (q.contextId && contextMap.has(q.contextId)) {
        result.contextBox = contextMap.get(q.contextId);
      }

      return result;
    });

  } catch (error) {
    console.error("Error analyzing test page:", error);
    throw new Error("Failed to analyze the image. Please try again.");
  }
};

import React, { useState, useEffect, useRef, useCallback } from 'react';
import Uploader from './components/Uploader';
import { analyzeTestPage } from './services/geminiService';
import { QuestionRegion, AppStatus, BoundingBox } from './types';
import { LoaderIcon, CheckIcon, DownloadIcon, ScissorsIcon } from './components/Icons';

export default function App() {
  const [status, setStatus] = useState<AppStatus>('IDLE');
  const [errorMsg, setErrorMsg] = useState<string>('');

  // Image data
  const [imageFile, setImageFile] = useState<File | null>(null);
  const [imageDataUrl, setImageDataUrl] = useState<string | null>(null);
  const [imageObj, setImageObj] = useState<HTMLImageElement | null>(null);

  // App Data
  const [regions, setRegions] = useState<QuestionRegion[]>([]);

  // Canvas Refs
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const containerRef = useRef<HTMLDivElement>(null);

  // Helper to generate a unique ID
  const generateId = () => Math.random().toString(36).substr(2, 9);

  // Handle new image upload
  const handleImageSelected = useCallback(async (dataUrl: string, file: File) => {
    setImageDataUrl(dataUrl);
    setImageFile(file);
    setStatus('ANALYZING');
    setErrorMsg('');
    setRegions([]);

    // Load image object for cropping later
    const img = new Image();
    img.onload = async () => {
      setImageObj(img);

      try {
        // Prepare base64 for API (remove data URI prefix)
        const base64String = dataUrl.split(',')[1];

        // Call Gemini API
        const detectedRegions = await analyzeTestPage(base64String, file.type);

        // Add IDs to regions
        const regionsWithIds: QuestionRegion[] = detectedRegions.map(r => ({
          ...r,
          id: generateId()
        }));

        setRegions(regionsWithIds);
        setStatus('READY');
      } catch (err: any) {
        setStatus('ERROR');
        setErrorMsg(err.message || "An error occurred during analysis.");
      }
    };
    img.onerror = () => {
      setStatus('ERROR');
      setErrorMsg("Failed to load the image locally.");
    };
    img.src = dataUrl;
  }, []);

  // Process crops when regions or imageObj changes
  useEffect(() => {
    if (status === 'READY' && imageObj && regions.length > 0 && !regions[0].croppedDataUrl) {
      const generateCrops = async () => {
        const updatedRegions = [...regions];
        for (let i = 0; i < updatedRegions.length; i++) {
          const region = updatedRegions[i];
          if (!region.croppedDataUrl) {
             updatedRegions[i] = {
                 ...region,
                 croppedDataUrl: cropImage(imageObj, region.box, region.contextBox)
             };
          }
        }
        setRegions(updatedRegions);
      };
      generateCrops();
    }
  // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [status, imageObj, regions]);


  // Draw main canvas
  useEffect(() => {
    if (status !== 'READY' && status !== 'ANALYZING') return;
    if (!imageObj || !canvasRef.current || !containerRef.current) return;

    const canvas = canvasRef.current;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    const container = containerRef.current;

    // Fit canvas to container while maintaining aspect ratio
    const containerRatio = container.clientWidth / container.clientHeight;
    const imageRatio = imageObj.width / imageObj.height;

    let drawWidth = container.clientWidth;
    let drawHeight = container.clientHeight;

    if (containerRatio > imageRatio) {
      drawWidth = drawHeight * imageRatio;
    } else {
      drawHeight = drawWidth / imageRatio;
    }

    canvas.width = drawWidth;
    canvas.height = drawHeight;

    // Draw image
    ctx.drawImage(imageObj, 0, 0, drawWidth, drawHeight);

    // Draw overlays if READY
    if (status === 'READY') {
      // 1. Draw Context Boxes first (so they are visually underneath question boxes if they get close)
      const drawnContexts = new Set<string>();
      regions.forEach(region => {
        if (region.contextBox) {
          const c = region.contextBox;
          const key = `${c.xmin},${c.ymin},${c.xmax},${c.ymax}`;

          if (!drawnContexts.has(key)) {
            drawnContexts.add(key);

            const startX = (c.xmin / 1000) * drawWidth;
            const startY = (c.ymin / 1000) * drawHeight;
            const width = ((c.xmax - c.xmin) / 1000) * drawWidth;
            const height = ((c.ymax - c.ymin) / 1000) * drawHeight;

            // Draw dashed purple rectangle
            ctx.beginPath();
            ctx.rect(startX, startY, width, height);
            ctx.fillStyle = 'rgba(168, 85, 247, 0.1)'; 
            ctx.fill();
            ctx.lineWidth = 2;
            ctx.setLineDash([6, 4]);
            ctx.strokeStyle = 'rgba(168, 85, 247, 0.8)';
            ctx.stroke();
            ctx.setLineDash([]); // Reset dash

            // Context Badge
            ctx.fillStyle = 'rgba(168, 85, 247, 0.9)';
            ctx.font = 'bold 12px sans-serif';
            ctx.fillRect(startX, startY - 20 > 0 ? startY - 20 : startY, 56, 20);
            ctx.fillStyle = 'white';
            ctx.fillText("Context", startX + 6, startY - 20 > 0 ? startY - 5 : startY + 14);
          }
        }
      });

      // 2. Draw Question Boxes
      regions.forEach(region => {
        const { ymin, xmin, ymax, xmax } = region.box;

        // Convert 0-1000 scale to actual canvas pixels
        const startX = (xmin / 1000) * drawWidth;
        const startY = (ymin / 1000) * drawHeight;
        const width = ((xmax - xmin) / 1000) * drawWidth;
        const height = ((ymax - ymin) / 1000) * drawHeight;

        // Draw rectangle
        ctx.beginPath();
        ctx.rect(startX, startY, width, height);

        if (region.isSelected) {
          ctx.fillStyle = 'rgba(34, 197, 94, 0.2)'; // Brand color with opacity
          ctx.fill();
          ctx.lineWidth = 3;
          ctx.strokeStyle = '#16a34a';
        } else {
           ctx.fillStyle = 'rgba(59, 130, 246, 0.1)'; // Blue with opacity
           ctx.fill();
           ctx.lineWidth = 2;
           ctx.strokeStyle = 'rgba(59, 130, 246, 0.8)';
        }
        ctx.stroke();

        // Draw Badge
        ctx.fillStyle = region.isSelected ? '#16a34a' : 'rgba(59, 130, 246, 0.9)';
        ctx.font = 'bold 14px sans-serif';
        const text = `Q${region.questionNumber}`;
        const textMetrics = ctx.measureText(text);
        const textWidth = textMetrics.width;

        // Badge background
        ctx.fillRect(startX, startY - 24 > 0 ? startY - 24 : startY, textWidth + 16, 24);

        // Badge text
        ctx.fillStyle = 'white';
        ctx.fillText(text, startX + 8, (startY - 24 > 0 ? startY - 8 : startY + 16));
      });
    }

  }, [imageObj, regions, status, containerRef.current?.clientWidth, containerRef.current?.clientHeight]); 

  // Handle Resize to re-draw canvas
  useEffect(() => {
    const handleResize = () => {
        // Trigger a fake state update to force re-evaluation of canvas draw
        setRegions(prev => [...prev]);
    };
    window.addEventListener('resize', handleResize);
    return () => window.removeEventListener('resize', handleResize);
  }, []);


  // Helper function to crop the actual high-res image and optionally stitch context
  const cropImage = (img: HTMLImageElement, qBox: BoundingBox, cBox?: BoundingBox): string => {
    const offscreenCanvas = document.createElement('canvas');
    const ctx = offscreenCanvas.getContext('2d');
    if (!ctx) return '';

    const paddingX = img.width * 0.01;
    const paddingY = img.height * 0.01;

    // Helper to calculate exact pixel coordinates with bounds checking
    const getCoords = (box: BoundingBox) => {
      const sx = Math.max(0, (box.xmin / 1000) * img.width - paddingX);
      const sy = Math.max(0, (box.ymin / 1000) * img.height - paddingY);
      const sw = Math.min(img.width - sx, ((box.xmax - box.xmin) / 1000) * img.width + paddingX * 2);
      const sh = Math.min(img.height - sy, ((box.ymax - box.ymin) / 1000) * img.height + paddingY * 2);
      return { sx, sy, sw, sh };
    };

    const q = getCoords(qBox);

    if (!cBox) {
      // Standard single crop
      offscreenCanvas.width = q.sw;
      offscreenCanvas.height = q.sh;
      ctx.fillStyle = '#ffffff';
      ctx.fillRect(0, 0, q.sw, q.sh);
      ctx.drawImage(img, q.sx, q.sy, q.sw, q.sh, 0, 0, q.sw, q.sh);
    } else {
      // Complex crop: Stitch Context Block on top of Question Block
      const c = getCoords(cBox);
      const gap = 30; // 30px gap for clarity between context and question

      // Canvas needs to be wide enough for the widest block, and tall enough for both + gap
      offscreenCanvas.width = Math.max(c.sw, q.sw);
      offscreenCanvas.height = c.sh + gap + q.sh;

      // Fill background
      ctx.fillStyle = '#ffffff';
      ctx.fillRect(0, 0, offscreenCanvas.width, offscreenCanvas.height);

      // Draw Context
      ctx.drawImage(img, c.sx, c.sy, c.sw, c.sh, 0, 0, c.sw, c.sh);

      // Draw neat divider line
      ctx.beginPath();
      ctx.moveTo(20, c.sh + gap / 2);
      ctx.lineTo(offscreenCanvas.width - 20, c.sh + gap / 2);
      ctx.strokeStyle = '#cbd5e1'; // slate-300
      ctx.lineWidth = 2;
      ctx.setLineDash([8, 8]);
      ctx.stroke();
      ctx.setLineDash([]); // reset

      // Draw Question
      ctx.drawImage(img, q.sx, q.sy, q.sw, q.sh, 0, c.sh + gap, q.sw, q.sh);
    }

    return offscreenCanvas.toDataURL('image/jpeg', 0.9); // Quality 0.9
  };

  const handleDownloadCrop = (region: QuestionRegion) => {
    if (!region.croppedDataUrl) return;
    const link = document.createElement('a');
    link.href = region.croppedDataUrl;
    link.download = `Question_${region.questionNumber}.jpg`;
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  };

  const handleDownloadAll = () => {
    regions.forEach(region => {
      if (region.croppedDataUrl) {
         // Slight delay to prevent browser blocking multiple rapid downloads
         setTimeout(() => handleDownloadCrop(region), 100);
      }
    });
  };

  const handleSelectRegion = (id: string) => {
    setRegions(prev => prev.map(r => ({
      ...r,
      isSelected: r.id === id
    })));
  };

  const handleReset = () => {
    setStatus('IDLE');
    setImageFile(null);
    setImageDataUrl(null);
    setImageObj(null);
    setRegions([]);
  };

  return (
    <>
      <header className="bg-white border-b border-gray-200 px-6 py-4 flex items-center justify-between shrink-0 sticky top-0 z-10">
        <div className="flex items-center gap-3">
          <div className="bg-brand-500 text-white p-2 rounded-lg">
            <ScissorsIcon className="w-5 h-5" />
          </div>
          <h1 className="text-xl font-bold text-gray-800 tracking-tight">Q-Crop</h1>
        </div>

        {status !== 'IDLE' && (
          <button 
            onClick={handleReset}
            className="text-sm font-medium text-gray-500 hover:text-gray-800 transition-colors"
          >
            Start Over
          </button>
        )}
      </header>

      <main className="flex-1 flex overflow-hidden">
        {status === 'IDLE' && (
           <Uploader onImageSelected={handleImageSelected} isLoading={false} />
        )}

        {(status === 'ANALYZING' || status === 'ERROR') && !regions.length && (
           <div className="flex-1 flex flex-col items-center justify-center p-8 text-center bg-gray-50">
              {status === 'ANALYZING' && (
                 <>
                   <LoaderIcon className="w-12 h-12 text-brand-500 mb-6" />
                   <h2 className="text-2xl font-semibold text-gray-800 mb-2">Analyzing Document...</h2>
                   <p className="text-gray-500 max-w-md">Our AI is scanning the image to map out individual questions and shared paragraphs. This usually takes a few seconds.</p>
                 </>
              )}
              {status === 'ERROR' && (
                 <>
                   <div className="w-16 h-16 bg-red-100 text-red-600 rounded-full flex items-center justify-center mb-6">
                      <svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" strokeWidth={1.5} stroke="currentColor" className="w-8 h-8">
                        <path strokeLinecap="round" strokeLinejoin="round" d="M12 9v2m0 4h.01m-6.938 4h13.856c1.54 0 2.502-1.667 1.732-3L13.732 4c-.77-1.333-2.694-1.333-3.464 0L3.34 16c-.77 1.333.192 3 1.732 3z" />
                      </svg>
                   </div>
                   <h2 className="text-2xl font-semibold text-gray-800 mb-2">Analysis Failed</h2>
                   <p className="text-red-500 mb-6 max-w-md">{errorMsg}</p>
                   <button 
                     onClick={handleReset}
                     className="px-6 py-2 bg-gray-800 text-white rounded-lg hover:bg-gray-700 font-medium transition-colors"
                   >
                     Try Another Image
                   </button>
                 </>
              )}
           </div>
        )}

        {/* Main Workspace Workspace */}
        {(status === 'READY' || (status === 'ANALYZING' && imageDataUrl)) && (
          <div className="flex-1 flex w-full h-full">

            {/* Canvas Area */}
            <div className="flex-1 bg-gray-200 p-4 overflow-hidden relative" ref={containerRef}>
                <div className="w-full h-full flex items-center justify-center relative shadow-inner bg-gray-300 rounded-lg overflow-hidden border border-gray-300">
                    <canvas 
                      ref={canvasRef} 
                      className="block max-w-full max-h-full shadow-lg bg-white"
                      style={{ objectFit: 'contain' }}
                    />

                    {/* Overlay Loader if re-analyzing */}
                    {status === 'ANALYZING' && (
                      <div className="absolute inset-0 bg-white/50 backdrop-blur-sm flex items-center justify-center z-10">
                         <LoaderIcon className="w-10 h-10 text-brand-600" />
                      </div>
                    )}
                </div>
            </div>

            {/* Sidebar */}
            <div className="w-96 bg-white border-l border-gray-200 flex flex-col shrink-0 shadow-[-4px_0_15px_-3px_rgba(0,0,0,0.05)] z-20">

              <div className="p-5 border-b border-gray-100 bg-gray-50/50 shrink-0">
                <div className="flex justify-between items-center mb-1">
                  <h2 className="text-lg font-bold text-gray-800">Detected Questions</h2>
                  <span className="bg-brand-100 text-brand-700 text-xs font-bold px-2 py-1 rounded-full">
                    {regions.length} Found
                  </span>
                </div>
                <p className="text-sm text-gray-500 mb-4">Review crops and export individually or all at once.</p>

                <button
                  onClick={handleDownloadAll}
                  disabled={regions.length === 0 || !regions.every(r => r.croppedDataUrl)}
                  className="w-full bg-brand-600 hover:bg-brand-700 text-white font-medium py-2.5 px-4 rounded-lg flex items-center justify-center gap-2 transition-colors disabled:opacity-50 disabled:cursor-not-allowed shadow-sm"
                >
                  <DownloadIcon className="w-5 h-5" />
                  Export All as JPG ZIP
                </button>
              </div>

              <div className="flex-1 overflow-y-auto p-4 space-y-4">
                {regions.map((region) => (
                  <div 
                    key={region.id} 
                    className={`border rounded-xl overflow-hidden transition-all duration-200 shadow-sm
                      ${region.isSelected ? 'border-brand-500 ring-2 ring-brand-100' : 'border-gray-200 hover:border-gray-300'}
                    `}
                    onClick={() => handleSelectRegion(region.id)}
                  >
                    <div className="bg-gray-50 px-3 py-2 border-b border-gray-100 flex justify-between items-center cursor-pointer">
                      <span className="font-semibold text-gray-700 flex items-center gap-2">
                         <div className={`w-2 h-2 rounded-full ${region.isSelected ? 'bg-brand-500' : 'bg-gray-300'}`}></div>
                         Question {region.questionNumber}
                      </span>
                      <button
                        onClick={(e) => { e.stopPropagation(); handleDownloadCrop(region); }}
                        disabled={!region.croppedDataUrl}
                        className="text-gray-400 hover:text-brand-600 p-1 rounded transition-colors disabled:opacity-50"
                        title="Download this crop"
                      >
                         <DownloadIcon className="w-5 h-5" />
                      </button>
                    </div>

                    <div className="bg-white p-3 cursor-pointer relative group">
                      {region.croppedDataUrl ? (
                         <>
                           <img 
                              src={region.croppedDataUrl} 
                              alt={`Crop for question ${region.questionNumber}`}
                              className="w-full h-auto max-h-48 object-contain rounded border border-gray-100 bg-gray-50"
                           />
                           {region.contextBox && (
                             <span className="absolute top-4 left-4 bg-purple-100 text-purple-700 text-[10px] font-bold px-2 py-0.5 rounded shadow-sm opacity-90">
                               Includes Context
                             </span>
                           )}
                           <div className="absolute inset-0 bg-black/5 opacity-0 group-hover:opacity-100 transition-opacity flex items-center justify-center pointer-events-none">
                              <span className="bg-white/90 text-gray-800 text-xs font-semibold px-2 py-1 rounded shadow-sm">View</span>
                           </div>
                         </>
                      ) : (
                         <div className="w-full h-24 flex items-center justify-center bg-gray-50 text-gray-400 text-sm">
                           Processing...
                         </div>
                      )}
                    </div>
                  </div>
                ))}

                {regions.length === 0 && status === 'READY' && (
                   <div className="text-center py-10 text-gray-500">
                     <p>No questions detected.</p>
                     <p className="text-sm mt-2">Try a clearer image or a different page.</p>
                   </div>
                )}
              </div>

            </div>
          </div>
        )}
      </main>
    </>
  );
}

import { GoogleGenAI, Type } from "@google/genai";
import { QuestionRegion } from "../types";

// Initialize AI inside functions to ensure latest API key if applicable
const getAI = () => new GoogleGenAI({ apiKey: process.env.API_KEY });

export const analyzeTestPage = async (base64Image: string, mimeType: string): Promise<Omit<QuestionRegion, 'id' | 'croppedDataUrl'>[]> => {
  const ai = getAI();

  const prompt = `
    Analyze this image of a test paper or worksheet. 

    Sometimes, multiple questions refer to a shared block of text, a passage, an image, or a graph (e.g., "37 ve 38. soruları aşağıdaki parçaya göre cevaplayınız." or "Answer questions 37 and 38 based on the passage").

    Task 1: Identify "Shared Contexts". Draw bounding boxes around these shared passages/images along with their instructional text. Give each an ID (e.g., "c1", "c2").

    Task 2: Identify "Questions". 
    - Extract the 'questionNumber' as a string (e.g., "37", "38", "1").
    - The bounding box for the question MUST EXCLUDE the question number/label itself from the actual crop area.
    - For example, if the question in the image is "37. Bu parçada boş bırakılan...", the bounding box ('box') should start precisely at "Bu parçada..." and include all text, options (A, B, C, D, E), and associated visuals, but it MUST OMIT the "37." label.
    - If the question label is on the side, above, or floating, ensure the 'box' coordinates strictly capture the question body without that label.
    - DO NOT include the shared context in the question's bounding box. The question box should strictly contain just that specific question's body and options.
    - If a question relies on a shared context, include that context's ID in the 'contextId' field. If it does not, leave 'contextId' empty or omit it.

    IMPORTANT BOUNDING BOX RULES:
    - Coordinates MUST be integers between 0 and 1000.
    - They represent relative positions where [0,0] is the top-left corner of the image and [1000, 1000] is the bottom-right corner.
    - ymin: Top edge of the box
    - xmin: Left edge of the box
    - ymax: Bottom edge of the box
    - xmax: Right edge of the box
    - Ensure ymax is strictly greater than ymin, and xmax is strictly greater than xmin.
    - Keep the bounding box as tight as possible to the question body, ensuring the label is excluded while the text is fully preserved.
  `;

  try {
    const response = await ai.models.generateContent({
      model: "gemini-3-flash-preview", 
      contents: [
        {
          inlineData: {
            data: base64Image,
            mimeType: mimeType,
          },
        },
        { text: prompt }
      ],
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          description: "Structured test page data with shared contexts and questions.",
          properties: {
            sharedContexts: {
              type: Type.ARRAY,
              items: {
                type: Type.OBJECT,
                properties: {
                  id: { type: Type.STRING },
                  ymin: { type: Type.INTEGER },
                  xmin: { type: Type.INTEGER },
                  ymax: { type: Type.INTEGER },
                  xmax: { type: Type.INTEGER }
                },
                required: ["id", "ymin", "xmin", "ymax", "xmax"]
              }
            },
            questions: {
              type: Type.ARRAY,
              items: {
                type: Type.OBJECT,
                properties: {
                  questionNumber: { type: Type.STRING },
                  ymin: { type: Type.INTEGER },
                  xmin: { type: Type.INTEGER },
                  ymax: { type: Type.INTEGER },
                  xmax: { type: Type.INTEGER },
                  contextId: { type: Type.STRING, description: "ID of the shared context block this question relies on. Leave empty if none." }
                },
                required: ["questionNumber", "ymin", "xmin", "ymax", "xmax"]
              }
            }
          },
          required: ["sharedContexts", "questions"]
        }
      }
    });

    if (!response.text) {
      throw new Error("Empty response from AI");
    }

    const parsedData = JSON.parse(response.text);
    const contexts = parsedData.sharedContexts || [];
    const questions = parsedData.questions || [];

    // Create a lookup map for context bounding boxes
    const contextMap = new Map();
    contexts.forEach((c: any) => {
      if (c.id) {
        contextMap.set(c.id, {
          ymin: c.ymin, xmin: c.xmin, ymax: c.ymax, xmax: c.xmax
        });
      }
    });

    // Map the raw JSON response to our expected interface format
    return questions.map((q: any) => {
      const result: Omit<QuestionRegion, 'id' | 'croppedDataUrl'> = {
        questionNumber: q.questionNumber,
        box: { ymin: q.ymin, xmin: q.xmin, ymax: q.ymax, xmax: q.xmax }
      };

      // If this question maps to a shared context, attach that bounding box
      if (q.contextId && contextMap.has(q.contextId)) {
        result.contextBox = contextMap.get(q.contextId);
      }

      return result;
    });

  } catch (error) {
    console.error("Error analyzing test page:", error);
    throw new Error("Failed to analyze the image. Please try again.");
  }
};

import { GoogleGenAI, Type } from "@google/genai";
import { QuestionRegion } from "../types";

// Initialize AI inside functions to ensure latest API key if applicable
const getAI = () => new GoogleGenAI({ apiKey: process.env.API_KEY });

export const analyzeTestPage = async (base64Image: string, mimeType: string): Promise<Omit<QuestionRegion, 'id' | 'croppedDataUrl'>[]> => {
  const ai = getAI();

  const prompt = `
    Analyze this image of a test paper or worksheet. 

    CRITICAL REQUIREMENT: EXCLUDE QUESTION LABELS FROM CROPS
    The user wants "clean" crops of the question content. 
    The question numbers (e.g., "37.", "38.", "Q1") must be detected for metadata purposes, but they MUST NOT be inside the bounding box coordinates for the question body.

    Task 1: Identify "Shared Contexts". 
    - Draw bounding boxes around shared passages/images along with their instructional text (e.g. "37 ve 38. soruları..."). 
    - Give each an ID (e.g., "c1", "c2").

    Task 2: Identify "Questions". 
    - Extract the 'questionNumber' as a string (e.g., "37", "38").
    - Find the bounding box ('box') for the question body.
    - IMPORTANT: The 'box' MUST START AFTER the question number and its trailing punctuation (like '.' or ')').
    - If the text is "37. Bu parçada...", the box xmin/ymin must start exactly at the "B" of "Bu".
    - Do not include the question number, the dot, or the space immediately following the number in the bounding box.
    - Ensure all options (A, B, C, D, E) and the full text are included.
    - If a question relies on a shared context, include that context's 'contextId'.

    OUTPUT JSON FORMAT:
    {
      "sharedContexts": [{"id": "c1", "ymin": 0, "xmin": 0, "ymax": 0, "xmax": 0}],
      "questions": [{"questionNumber": "37", "ymin": 0, "xmin": 0, "ymax": 0, "xmax": 0, "contextId": "c1"}]
    }

    COORDINATE RULES:
    - Values 0-1000 relative to image size.
    - Be extremely precise. Even 1-2 units too far left might include the number. Err on the side of starting the box 2-3 units to the right of the actual number label.
  `;

  try {
    const response = await ai.models.generateContent({
      model: "gemini-3-flash-preview", 
      contents: [
        {
          inlineData: {
            data: base64Image,
            mimeType: mimeType,
          },
        },
        { text: prompt }
      ],
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          description: "Structured test page data with shared contexts and questions body strictly excluded from labels.",
          properties: {
            sharedContexts: {
              type: Type.ARRAY,
              items: {
                type: Type.OBJECT,
                properties: {
                  id: { type: Type.STRING },
                  ymin: { type: Type.INTEGER },
                  xmin: { type: Type.INTEGER },
                  ymax: { type: Type.INTEGER },
                  xmax: { type: Type.INTEGER }
                },
                required: ["id", "ymin", "xmin", "ymax", "xmax"]
              }
            },
            questions: {
              type: Type.ARRAY,
              items: {
                type: Type.OBJECT,
                properties: {
                  questionNumber: { type: Type.STRING },
                  ymin: { type: Type.INTEGER },
                  xmin: { type: Type.INTEGER },
                  ymax: { type: Type.INTEGER },
                  xmax: { type: Type.INTEGER },
                  contextId: { type: Type.STRING }
                },
                required: ["questionNumber", "ymin", "xmin", "ymax", "xmax"]
              }
            }
          },
          required: ["sharedContexts", "questions"]
        }
      }
    });

    if (!response.text) {
      throw new Error("Empty response from AI");
    }

    const parsedData = JSON.parse(response.text);
    const contexts = parsedData.sharedContexts || [];
    const questions = parsedData.questions || [];

    const contextMap = new Map();
    contexts.forEach((c: any) => {
      if (c.id) {
        contextMap.set(c.id, {
          ymin: c.ymin, xmin: c.xmin, ymax: c.ymax, xmax: c.xmax
        });
      }
    });

    return questions.map((q: any) => {
      const result: Omit<QuestionRegion, 'id' | 'croppedDataUrl'> = {
        questionNumber: q.questionNumber,
        box: { ymin: q.ymin, xmin: q.xmin, ymax: q.ymax, xmax: q.xmax }
      };

      if (q.contextId && contextMap.has(q.contextId)) {
        result.contextBox = contextMap.get(q.contextId);
      }

      return result;
    });

  } catch (error) {
    console.error("Error analyzing test page:", error);
    throw new Error("Failed to analyze the image. Please try again.");
  }
};

import React, { useState, useEffect, useRef, useCallback } from 'react';
import Uploader from './components/Uploader';
import { analyzeTestPage } from './services/geminiService';
import { QuestionRegion, AppStatus, BoundingBox } from './types';
import { LoaderIcon, CheckIcon, DownloadIcon, ScissorsIcon } from './components/Icons';

export default function App() {
  const [status, setStatus] = useState<AppStatus>('IDLE');
  const [errorMsg, setErrorMsg] = useState<string>('');

  // Image data
  const [imageFile, setImageFile] = useState<File | null>(null);
  const [imageDataUrl, setImageDataUrl] = useState<string | null>(null);
  const [imageObj, setImageObj] = useState<HTMLImageElement | null>(null);

  // App Data
  const [regions, setRegions] = useState<QuestionRegion[]>([]);

  // Canvas Refs
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const containerRef = useRef<HTMLDivElement>(null);

  // Helper to generate a unique ID
  const generateId = () => Math.random().toString(36).substr(2, 9);

  // Handle new image upload
  const handleImageSelected = useCallback(async (dataUrl: string, file: File) => {
    setImageDataUrl(dataUrl);
    setImageFile(file);
    setStatus('ANALYZING');
    setErrorMsg('');
    setRegions([]);

    // Load image object for cropping later
    const img = new Image();
    img.onload = async () => {
      setImageObj(img);

      try {
        // Prepare base64 for API (remove data URI prefix)
        const base64String = dataUrl.split(',')[1];

        // Call Gemini API
        const detectedRegions = await analyzeTestPage(base64String, file.type);

        // Add IDs to regions
        const regionsWithIds: QuestionRegion[] = detectedRegions.map(r => ({
          ...r,
          id: generateId()
        }));

        setRegions(regionsWithIds);
        setStatus('READY');
      } catch (err: any) {
        setStatus('ERROR');
        setErrorMsg(err.message || "An error occurred during analysis.");
      }
    };
    img.onerror = () => {
      setStatus('ERROR');
      setErrorMsg("Failed to load the image locally.");
    };
    img.src = dataUrl;
  }, []);

  // Process crops when regions or imageObj changes
  useEffect(() => {
    if (status === 'READY' && imageObj && regions.length > 0 && !regions[0].croppedDataUrl) {
      const generateCrops = async () => {
        const updatedRegions = [...regions];
        for (let i = 0; i < updatedRegions.length; i++) {
          const region = updatedRegions[i];
          if (!region.croppedDataUrl) {
             updatedRegions[i] = {
                 ...region,
                 croppedDataUrl: cropImage(imageObj, region.box, region.contextBox)
             };
          }
        }
        setRegions(updatedRegions);
      };
      generateCrops();
    }
  // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [status, imageObj, regions]);


  // Draw main canvas
  useEffect(() => {
    if (status !== 'READY' && status !== 'ANALYZING') return;
    if (!imageObj || !canvasRef.current || !containerRef.current) return;

    const canvas = canvasRef.current;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    const container = containerRef.current;

    // Fit canvas to container while maintaining aspect ratio
    const containerRatio = container.clientWidth / container.clientHeight;
    const imageRatio = imageObj.width / imageObj.height;

    let drawWidth = container.clientWidth;
    let drawHeight = container.clientHeight;

    if (containerRatio > imageRatio) {
      drawWidth = drawHeight * imageRatio;
    } else {
      drawHeight = drawWidth / imageRatio;
    }

    canvas.width = drawWidth;
    canvas.height = drawHeight;

    // Draw image
    ctx.drawImage(imageObj, 0, 0, drawWidth, drawHeight);

    // Draw overlays if READY
    if (status === 'READY') {
      // 1. Draw Context Boxes first
      const drawnContexts = new Set<string>();
      regions.forEach(region => {
        if (region.contextBox) {
          const c = region.contextBox;
          const key = `${c.xmin},${c.ymin},${c.xmax},${c.ymax}`;

          if (!drawnContexts.has(key)) {
            drawnContexts.add(key);

            const startX = (c.xmin / 1000) * drawWidth;
            const startY = (c.ymin / 1000) * drawHeight;
            const width = ((c.xmax - c.xmin) / 1000) * drawWidth;
            const height = ((c.ymax - c.ymin) / 1000) * drawHeight;

            ctx.beginPath();
            ctx.rect(startX, startY, width, height);
            ctx.fillStyle = 'rgba(168, 85, 247, 0.05)'; 
            ctx.fill();
            ctx.lineWidth = 1;
            ctx.setLineDash([4, 4]);
            ctx.strokeStyle = 'rgba(168, 85, 247, 0.4)';
            ctx.stroke();
            ctx.setLineDash([]); 
          }
        }
      });

      // 2. Draw Question Boxes
      regions.forEach(region => {
        const { ymin, xmin, ymax, xmax } = region.box;

        const startX = (xmin / 1000) * drawWidth;
        const startY = (ymin / 1000) * drawHeight;
        const width = ((xmax - xmin) / 1000) * drawWidth;
        const height = ((ymax - ymin) / 1000) * drawHeight;

        ctx.beginPath();
        ctx.rect(startX, startY, width, height);

        if (region.isSelected) {
          ctx.fillStyle = 'rgba(34, 197, 94, 0.2)';
          ctx.fill();
          ctx.lineWidth = 2;
          ctx.strokeStyle = '#16a34a';
        } else {
           ctx.fillStyle = 'rgba(59, 130, 246, 0.1)';
           ctx.fill();
           ctx.lineWidth = 1.5;
           ctx.strokeStyle = 'rgba(59, 130, 246, 0.6)';
        }
        ctx.stroke();

        ctx.fillStyle = region.isSelected ? '#16a34a' : 'rgba(59, 130, 246, 0.8)';
        ctx.font = 'bold 12px sans-serif';
        const text = `Q${region.questionNumber}`;
        const textMetrics = ctx.measureText(text);
        const textWidth = textMetrics.width;

        ctx.fillRect(startX, startY - 20 > 0 ? startY - 20 : startY, textWidth + 12, 20);
        ctx.fillStyle = 'white';
        ctx.fillText(text, startX + 6, (startY - 20 > 0 ? startY - 6 : startY + 14));
      });
    }

  }, [imageObj, regions, status, containerRef.current?.clientWidth, containerRef.current?.clientHeight]); 

  useEffect(() => {
    const handleResize = () => setRegions(prev => [...prev]);
    window.addEventListener('resize', handleResize);
    return () => window.removeEventListener('resize', handleResize);
  }, []);

  const cropImage = (img: HTMLImageElement, qBox: BoundingBox, cBox?: BoundingBox): string => {
    const offscreenCanvas = document.createElement('canvas');
    const ctx = offscreenCanvas.getContext('2d');
    if (!ctx) return '';

    // Very minimal padding to avoid including nearby labels
    const paddingX = img.width * 0.005; 
    const paddingY = img.height * 0.005;

    const getCoords = (box: BoundingBox, isQuestion: boolean) => {
      // For questions, we use even less left-padding because the label is usually on the left
      const leftPad = isQuestion ? img.width * 0.002 : paddingX; 

      const sx = Math.max(0, (box.xmin / 1000) * img.width - leftPad);
      const sy = Math.max(0, (box.ymin / 1000) * img.height - paddingY);
      const sw = Math.min(img.width - sx, ((box.xmax - box.xmin) / 1000) * img.width + (leftPad + paddingX));
      const sh = Math.min(img.height - sy, ((box.ymax - box.ymin) / 1000) * img.height + paddingY * 2);
      return { sx, sy, sw, sh };
    };

    const q = getCoords(qBox, true);

    if (!cBox) {
      offscreenCanvas.width = q.sw;
      offscreenCanvas.height = q.sh;
      ctx.fillStyle = '#ffffff';
      ctx.fillRect(0, 0, q.sw, q.sh);
      ctx.drawImage(img, q.sx, q.sy, q.sw, q.sh, 0, 0, q.sw, q.sh);
    } else {
      const c = getCoords(cBox, false);
      const gap = 40; 

      offscreenCanvas.width = Math.max(c.sw, q.sw);
      offscreenCanvas.height = c.sh + gap + q.sh;

      ctx.fillStyle = '#ffffff';
      ctx.fillRect(0, 0, offscreenCanvas.width, offscreenCanvas.height);

      // Center horizontally if widths differ
      const cOffsetX = (offscreenCanvas.width - c.sw) / 2;
      const qOffsetX = (offscreenCanvas.width - q.sw) / 2;

      ctx.drawImage(img, c.sx, c.sy, c.sw, c.sh, cOffsetX, 0, c.sw, c.sh);

      ctx.beginPath();
      ctx.setLineDash([10, 10]);
      ctx.moveTo(30, c.sh + gap / 2);
      ctx.lineTo(offscreenCanvas.width - 30, c.sh + gap / 2);
      ctx.strokeStyle = '#e2e8f0'; 
      ctx.lineWidth = 2;
      ctx.stroke();
      ctx.setLineDash([]); 

      ctx.drawImage(img, q.sx, q.sy, q.sw, q.sh, qOffsetX, c.sh + gap, q.sw, q.sh);
    }

    return offscreenCanvas.toDataURL('image/jpeg', 0.92);
  };

  const handleDownloadCrop = (region: QuestionRegion) => {
    if (!region.croppedDataUrl) return;
    const link = document.createElement('a');
    link.href = region.croppedDataUrl;
    link.download = `Q${region.questionNumber}_Clean.jpg`;
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  };

  const handleDownloadAll = () => {
    regions.forEach((region, idx) => {
      if (region.croppedDataUrl) {
         setTimeout(() => handleDownloadCrop(region), idx * 200);
      }
    });
  };

  const handleSelectRegion = (id: string) => {
    setRegions(prev => prev.map(r => ({
      ...r,
      isSelected: r.id === id
    })));
  };

  const handleReset = () => {
    setStatus('IDLE');
    setImageFile(null);
    setImageDataUrl(null);
    setImageObj(null);
    setRegions([]);
  };

  return (
    <>
      <header className="bg-white border-b border-gray-200 px-6 py-4 flex items-center justify-between shrink-0 sticky top-0 z-50">
        <div className="flex items-center gap-3">
          <div className="bg-brand-600 text-white p-2 rounded-xl shadow-sm">
            <ScissorsIcon className="w-5 h-5" />
          </div>
          <div>
            <h1 className="text-xl font-bold text-slate-900 tracking-tight leading-none mb-1">Q-Crop</h1>
            <p className="text-[10px] uppercase tracking-widest text-slate-400 font-bold">Clean Extraction Pro</p>
          </div>
        </div>

        {status !== 'IDLE' && (
          <button 
            onClick={handleReset}
            className="px-4 py-2 text-sm font-semibold text-slate-500 hover:text-slate-800 bg-slate-100 hover:bg-slate-200 rounded-lg transition-all"
          >
            Start Over
          </button>
        )}
      </header>

      <main className="flex-1 flex overflow-hidden">
        {status === 'IDLE' && (
           <Uploader onImageSelected={handleImageSelected} isLoading={false} />
        )}

        {(status === 'ANALYZING' || status === 'ERROR') && !regions.length && (
           <div className="flex-1 flex flex-col items-center justify-center p-8 text-center bg-gray-50">
              {status === 'ANALYZING' && (
                 <div className="bg-white p-12 rounded-3xl shadow-xl border border-slate-100 max-w-sm flex flex-col items-center">
                   <div className="relative mb-8">
                     <div className="absolute inset-0 bg-brand-200 rounded-full blur-2xl opacity-50 animate-pulse"></div>
                     <LoaderIcon className="w-16 h-16 text-brand-500 relative" />
                   </div>
                   <h2 className="text-2xl font-bold text-slate-800 mb-3">Cleaning Crops...</h2>
                   <p className="text-slate-500 text-sm leading-relaxed">Our AI is meticulously excluding labels and stitching context for a perfect export.</p>
                 </div>
              )}
              {status === 'ERROR' && (
                 <div className="bg-white p-12 rounded-3xl shadow-xl border border-red-100 max-w-sm flex flex-col items-center">
                   <div className="w-16 h-16 bg-red-50 text-red-500 rounded-full flex items-center justify-center mb-6">
                      <svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" strokeWidth={2} stroke="currentColor" className="w-8 h-8">
                        <path strokeLinecap="round" strokeLinejoin="round" d="M12 9v3.75m9-.75a9 9 0 11-18 0 9 9 0 0118 0zm-9 3.75h.008v.008H12v-.008z" />
                      </svg>
                   </div>
                   <h2 className="text-xl font-bold text-slate-800 mb-2">Analysis Failed</h2>
                   <p className="text-red-500 text-sm mb-8">{errorMsg}</p>
                   <button 
                     onClick={handleReset}
                     className="w-full py-3 bg-slate-900 text-white rounded-xl hover:bg-slate-800 font-bold transition-all shadow-lg shadow-slate-200"
                   >
                     Try Another Image
                   </button>
                 </div>
              )}
           </div>
        )}

        {(status === 'READY' || (status === 'ANALYZING' && imageDataUrl)) && (
          <div className="flex-1 flex w-full h-full">

            <div className="flex-1 bg-slate-100 p-6 overflow-hidden relative" ref={containerRef}>
                <div className="w-full h-full flex items-center justify-center relative shadow-2xl bg-slate-300/50 rounded-2xl overflow-hidden border border-slate-200/50">
                    <canvas 
                      ref={canvasRef} 
                      className="block max-w-full max-h-full shadow-2xl bg-white rounded-sm"
                      style={{ objectFit: 'contain' }}
                    />

                    {status === 'ANALYZING' && (
                      <div className="absolute inset-0 bg-white/40 backdrop-blur-[2px] flex items-center justify-center z-10">
                         <div className="bg-white px-6 py-4 rounded-2xl shadow-xl flex items-center gap-3">
                           <LoaderIcon className="w-5 h-5 text-brand-600" />
                           <span className="font-bold text-slate-700 text-sm">Updating Analysis...</span>
                         </div>
                      </div>
                    )}
                </div>
            </div>

            <div className="w-[400px] bg-white border-l border-slate-200 flex flex-col shrink-0 z-20 overflow-hidden">

              <div className="p-6 border-b border-slate-100 bg-slate-50/30 shrink-0">
                <div className="flex justify-between items-end mb-4">
                  <div>
                    <h2 className="text-lg font-bold text-slate-900">Output Preview</h2>
                    <p className="text-xs text-slate-500">Labels are removed from final images.</p>
                  </div>
                  <span className="bg-slate-900 text-white text-[10px] font-black px-2.5 py-1 rounded-md uppercase">
                    {regions.length} Items
                  </span>
                </div>

                <button
                  onClick={handleDownloadAll}
                  disabled={regions.length === 0 || !regions.every(r => r.croppedDataUrl)}
                  className="w-full bg-brand-600 hover:bg-brand-700 text-white font-bold py-3.5 px-4 rounded-xl flex items-center justify-center gap-2.5 transition-all disabled:opacity-30 disabled:grayscale shadow-lg shadow-brand-100 active:scale-[0.98]"
                >
                  <DownloadIcon className="w-5 h-5" />
                  Download All Clean Crops
                </button>
              </div>

              <div className="flex-1 overflow-y-auto p-6 space-y-6">
                {regions.map((region) => (
                  <div 
                    key={region.id} 
                    className={`group relative border-2 rounded-2xl overflow-hidden transition-all duration-300
                      ${region.isSelected ? 'border-brand-500 shadow-xl shadow-brand-50/50 scale-[1.02]' : 'border-slate-100 hover:border-slate-200'}
                    `}
                    onClick={() => handleSelectRegion(region.id)}
                  >
                    <div className={`px-4 py-2.5 flex justify-between items-center transition-colors ${region.isSelected ? 'bg-brand-50' : 'bg-slate-50'}`}>
                      <div className="flex items-center gap-2">
                        <span className={`text-[10px] font-black uppercase px-1.5 py-0.5 rounded ${region.isSelected ? 'bg-brand-600 text-white' : 'bg-slate-200 text-slate-600'}`}>
                          Q{region.questionNumber}
                        </span>
                        {region.contextBox && (
                          <span className="bg-purple-100 text-purple-700 text-[10px] font-black uppercase px-1.5 py-0.5 rounded">
                            + Context
                          </span>
                        )}
                      </div>
                      <button
                        onClick={(e) => { e.stopPropagation(); handleDownloadCrop(region); }}
                        disabled={!region.croppedDataUrl}
                        className="text-slate-400 hover:text-brand-600 p-1.5 rounded-lg hover:bg-white transition-all disabled:opacity-0"
                      >
                         <DownloadIcon className="w-4 h-4" />
                      </button>
                    </div>

                    <div className="bg-white p-4 cursor-pointer">
                      {region.croppedDataUrl ? (
                         <div className="relative">
                           <img 
                              src={region.croppedDataUrl} 
                              alt={`Crop for question ${region.questionNumber}`}
                              className="w-full h-auto max-h-64 object-contain rounded-lg border border-slate-50 bg-slate-50/20"
                           />
                           <div className="absolute top-2 right-2 flex gap-1 opacity-0 group-hover:opacity-100 transition-opacity">
                              <div className="bg-white/90 backdrop-blur shadow-sm border border-slate-100 px-2 py-1 rounded text-[9px] font-bold text-slate-500 uppercase">
                                Clean Crop
                              </div>
                           </div>
                         </div>
                      ) : (
                         <div className="w-full h-32 flex flex-col items-center justify-center bg-slate-50 rounded-lg animate-pulse">
                           <div className="w-8 h-8 rounded-full bg-slate-200 mb-2"></div>
                           <span className="text-[10px] text-slate-400 font-bold uppercase tracking-wider">Rendering...</span>
                         </div>
                      )}
                    </div>
                  </div>
                ))}

                {regions.length === 0 && status === 'READY' && (
                   <div className="text-center py-20 flex flex-col items-center">
                     <div className="w-16 h-16 bg-slate-50 rounded-full flex items-center justify-center mb-4">
                       <ScissorsIcon className="w-8 h-8 text-slate-300" />
                     </div>
                     <p className="font-bold text-slate-400 text-sm">No Questions Found</p>
                     <p className="text-slate-300 text-xs mt-1">Try a clearer image.</p>
                   </div>
                )}
              </div>

            </div>
          </div>
        )}
      </main>
    </>
  );
}

export interface BoundingBox {
  ymin: number;
  xmin: number;
  ymax: number;
  xmax: number;
}

export interface QuestionRegion {
  id: string;
  questionNumber: string;
  pageNumber: string; // The detected page number from the document
  box: BoundingBox;
  contextBox?: BoundingBox;
  croppedDataUrl?: string;
  isSelected?: boolean;
}

export interface PageData {
  id: string;
  file: File;
  dataUrl: string;
  imageObj: HTMLImageElement | null;
  status: AppStatus;
  regions: QuestionRegion[];
  pageNumber: string;
  error?: string;
}

export type AppStatus = 'IDLE' | 'ANALYZING' | 'READY' | 'ERROR';

import { GoogleGenAI, Type } from "@google/genai";
import { QuestionRegion } from "../types";

const getAI = () => new GoogleGenAI({ apiKey: process.env.API_KEY });

export interface AnalysisResult {
  pageNumber: string;
  regions: Omit<QuestionRegion, 'id' | 'croppedDataUrl' | 'pageNumber'>[];
}

export const analyzeTestPage = async (base64Image: string, mimeType: string): Promise<AnalysisResult> => {
  const ai = getAI();

  const prompt = `
    Analyze this image of a test paper or worksheet. 

    CRITICAL REQUIREMENTS:
    1. Detect the Page Number: Look for the page number of the document (usually at the very bottom center or corner). Extract it as a string (e.g., "11").
    2. EXCLUDE QUESTION LABELS FROM CROPS: Detect question numbers (e.g., "37.", "38.") but ensure the bounding box 'box' EXCLUDES these labels. The crop must be "clean".

    Task 1: Identify "Shared Contexts". 
    - Draw bounding boxes around shared passages/images along with their instructional text. 
    - Give each an ID (e.g., "c1").

    Task 2: Identify "Questions". 
    - Extract the 'questionNumber' as a string.
    - Find the bounding box ('box') for the question body strictly excluding the number label.
    - If a question relies on a shared context, include its 'contextId'.

    OUTPUT JSON FORMAT:
    {
      "pageNumber": "11",
      "sharedContexts": [{"id": "c1", "ymin": 0, "xmin": 0, "ymax": 0, "xmax": 0}],
      "questions": [{"questionNumber": "37", "ymin": 0, "xmin": 0, "ymax": 0, "xmax": 0, "contextId": "c1"}]
    }

    COORDINATE RULES: 0-1000 relative to image size. Be extremely precise.
  `;

  try {
    const response = await ai.models.generateContent({
      model: "gemini-3-flash-preview", 
      contents: [
        {
          inlineData: {
            data: base64Image,
            mimeType: mimeType,
          },
        },
        { text: prompt }
      ],
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          description: "Structured test page data with page number and clean crops.",
          properties: {
            pageNumber: { type: Type.STRING, description: "The page number found on the document page." },
            sharedContexts: {
              type: Type.ARRAY,
              items: {
                type: Type.OBJECT,
                properties: {
                  id: { type: Type.STRING },
                  ymin: { type: Type.INTEGER },
                  xmin: { type: Type.INTEGER },
                  ymax: { type: Type.INTEGER },
                  xmax: { type: Type.INTEGER }
                },
                required: ["id", "ymin", "xmin", "ymax", "xmax"]
              }
            },
            questions: {
              type: Type.ARRAY,
              items: {
                type: Type.OBJECT,
                properties: {
                  questionNumber: { type: Type.STRING },
                  ymin: { type: Type.INTEGER },
                  xmin: { type: Type.INTEGER },
                  ymax: { type: Type.INTEGER },
                  xmax: { type: Type.INTEGER },
                  contextId: { type: Type.STRING }
                },
                required: ["questionNumber", "ymin", "xmin", "ymax", "xmax"]
              }
            }
          },
          required: ["pageNumber", "sharedContexts", "questions"]
        }
      }
    });

    if (!response.text) throw new Error("Empty response from AI");

    const parsedData = JSON.parse(response.text);
    const contexts = parsedData.sharedContexts || [];
    const questions = parsedData.questions || [];
    const pageNum = parsedData.pageNumber || "unknown";

    const contextMap = new Map();
    contexts.forEach((c: any) => {
      if (c.id) {
        contextMap.set(c.id, { ymin: c.ymin, xmin: c.xmin, ymax: c.ymax, xmax: c.xmax });
      }
    });

    return {
      pageNumber: pageNum,
      regions: questions.map((q: any) => {
        const result: any = {
          questionNumber: q.questionNumber,
          box: { ymin: q.ymin, xmin: q.xmin, ymax: q.ymax, xmax: q.xmax }
        };
        if (q.contextId && contextMap.has(q.contextId)) {
          result.contextBox = contextMap.get(q.contextId);
        }
        return result;
      })
    };

  } catch (error) {
    console.error("Error analyzing test page:", error);
    throw new Error("Failed to analyze the page.");
  }
};

import React, { useCallback, useRef } from 'react';
import { UploadIcon } from './Icons';

interface UploaderProps {
  onImagesSelected: (files: { dataUrl: string, file: File }[]) => void;
  isLoading: boolean;
}

const Uploader: React.FC<UploaderProps> = ({ onImagesSelected, isLoading }) => {
  const fileInputRef = useRef<HTMLInputElement>(null);

  const handleFileChange = useCallback(async (event: React.ChangeEvent<HTMLInputElement>) => {
    const files = Array.from(event.target.files || []);
    const results: { dataUrl: string, file: File }[] = [];

    for (const file of files) {
      if (file.type.startsWith('image/')) {
        const dataUrl = await new Promise<string>((resolve) => {
          const reader = new FileReader();
          reader.onload = (e) => resolve(e.target?.result as string);
          reader.readAsDataURL(file);
        });
        results.push({ dataUrl, file });
      }
    }

    if (results.length > 0) {
      onImagesSelected(results);
    }

    if (fileInputRef.current) fileInputRef.current.value = '';
  }, [onImagesSelected]);

  return (
    <div className="flex flex-col items-center justify-center w-full h-full p-8 bg-slate-50">
      <div 
        className={`w-full max-w-2xl p-16 border-4 border-dashed rounded-[2.5rem] text-center transition-all duration-300 shadow-2xl shadow-slate-200/50
          ${isLoading ? 'border-slate-200 bg-slate-100 opacity-70 cursor-wait' : 'border-brand-300 bg-white hover:border-brand-500 hover:bg-brand-50/30 cursor-pointer hover:scale-[1.01]'}
        `}
        onClick={() => !isLoading && fileInputRef.current?.click()}
      >
        <div className="w-24 h-24 bg-brand-100 rounded-3xl flex items-center justify-center mx-auto mb-8 text-brand-600">
           <UploadIcon className="w-10 h-10" />
        </div>
        <h3 className="text-3xl font-black mb-3 text-slate-800 tracking-tight">Bulk Question Extractor</h3>
        <p className="text-slate-500 mb-10 text-lg">Select multiple exam pages to crop all questions at once.</p>

        <div className="inline-flex items-center gap-3 px-6 py-3 bg-brand-600 text-white rounded-2xl font-bold shadow-lg shadow-brand-200 hover:bg-brand-700 transition-all">
          <UploadIcon className="w-5 h-5" />
